"""Interfaces and links.

A :class:`Link` models the virtual Ethernet pair that Mininet uses to connect two
nodes; :class:`TCLink` adds the ``tc``-style shaping parameters (bandwidth,
delay and loss) that the simulation engine reads when computing throughput,
latency and reachability.
"""


class Intf:
    """A network interface belonging to a node."""

    def __init__(self, name, node=None, port=None, link=None, **params):
        self.name = name
        self.node = node
        self.port = port
        self.link = link
        self.params = dict(params)
        self.ip = params.get("ip")
        self.mac = params.get("mac")
        if node is not None:
            node.addIntf(self, port=port)

    def setIP(self, ip):
        self.ip = ip
        return ip

    def IP(self):
        return self.ip

    def setMAC(self, mac):
        self.mac = mac
        return mac

    def MAC(self):
        return self.mac

    def config(self, **kwargs):
        self.params.update(kwargs)
        return self.params

    def __repr__(self):
        return "<Intf %s>" % self.name

    def __str__(self):
        return self.name


class Link:
    """A bidirectional link between two nodes.

    Creates one :class:`Intf` on each side and stores the link characteristics
    used by the simulation engine: ``bw`` in Mbps, ``delay`` in milliseconds and
    ``loss`` as a percentage.
    """

    #: Bandwidth used when a link is created without an explicit value (Mbps).
    DEFAULT_BW = 1000.0
    #: One-way propagation delay used when none is given (milliseconds).
    DEFAULT_DELAY = 0.0
    #: Loss percentage used when none is given.
    DEFAULT_LOSS = 0.0

    def __init__(self, node1, node2, port1=None, port2=None,
                 intfName1=None, intfName2=None, cls1=Intf, cls2=Intf,
                 bw=None, delay=None, loss=None, **params):
        self.node1 = node1
        self.node2 = node2
        self.bw = float(bw) if bw is not None else float(self.DEFAULT_BW)
        self.delay = float(delay) if delay is not None else float(self.DEFAULT_DELAY)
        self.loss = float(loss) if loss is not None else float(self.DEFAULT_LOSS)
        self.params = dict(params)

        if port1 is None:
            port1 = node1.newPort()
        if port2 is None:
            port2 = node2.newPort()
        if intfName1 is None:
            intfName1 = self.intfName(node1, port1)
        if intfName2 is None:
            intfName2 = self.intfName(node2, port2)

        self.intf1 = cls1(intfName1, node=node1, port=port1, link=self)
        self.intf2 = cls2(intfName2, node=node2, port=port2, link=self)
        self.port1 = self.intf1.port
        self.port2 = self.intf2.port

    @staticmethod
    def intfName(node, port):
        """Mininet-style interface name, e.g. ``s1-eth0``."""
        return "%s-eth%d" % (node.name, port)

    # ------------------------------------------------------------------
    @property
    def loss_fraction(self):
        """Loss expressed on a 0-1 scale (``loss`` is a percentage)."""
        return self.loss / 100.0

    def endpoints(self):
        return (self.node1, self.node2)

    def other(self, node):
        """Return the node at the far end of the link."""
        name = getattr(node, "name", node)
        if self.node1.name == name:
            return self.node2
        if self.node2.name == name:
            return self.node1
        return None

    def intf(self, node):
        """Return the interface belonging to ``node``."""
        name = getattr(node, "name", node)
        if self.node1.name == name:
            return self.intf1
        if self.node2.name == name:
            return self.intf2
        return None

    def otherIntf(self, intf):
        """Return the interface on the opposite side of ``intf``."""
        if intf is self.intf1:
            return self.intf2
        if intf is self.intf2:
            return self.intf1
        return None

    def connects(self, node1, node2):
        n1 = getattr(node1, "name", node1)
        n2 = getattr(node2, "name", node2)
        pair = {self.node1.name, self.node2.name}
        return pair == {n1, n2}

    def attrs(self):
        """Link characteristics as a dict (the payload stored on graph edges)."""
        d = {"bw": self.bw, "delay": self.delay, "loss": self.loss, "link": self}
        d.update(self.params)
        return d

    def status(self):
        return "(OK OK)"

    def delete(self):
        for node, intf in ((self.node1, self.intf1), (self.node2, self.intf2)):
            if intf.port in node.intfs and node.intfs[intf.port] is intf:
                del node.intfs[intf.port]
        self.intf1.link = None
        self.intf2.link = None

    def __repr__(self):
        return "<%s %s<->%s>" % (self.__class__.__name__,
                                 self.intf1.name, self.intf2.name)

    def __str__(self):
        return "%s<->%s" % (self.intf1.name, self.intf2.name)


class TCLink(Link):
    """Traffic-controlled link with explicit bandwidth, delay and loss.

    Parameters
    ----------
    bw : float
        Bandwidth in Mbps.
    delay : float
        One-way delay in milliseconds.
    loss : float
        Loss rate as a percentage (0-100).
    """

    def __init__(self, node1, node2, bw=1000.0, delay=0.0, loss=0.0,
                 max_queue_size=None, use_htb=True, **params):
        self.max_queue_size = max_queue_size
        self.use_htb = use_htb
        Link.__init__(self, node1, node2, bw=bw, delay=delay, loss=loss,
                      **params)

    def config(self, **kwargs):
        """Update shaping parameters after creation."""
        if "bw" in kwargs:
            self.bw = float(kwargs.pop("bw"))
        if "delay" in kwargs:
            self.delay = float(kwargs.pop("delay"))
        if "loss" in kwargs:
            self.loss = float(kwargs.pop("loss"))
        self.params.update(kwargs)
        return self.attrs()

"""Topology templates.

A :class:`Topo` is a *blueprint*: it records hosts, switches and links without
instantiating any node object.  :class:`netsim.net.Mininet` consumes the
blueprint in :meth:`netsim.net.Mininet.build` and creates the real objects.
"""

from .graph import WeightedGraph


class Topo:
    """Base topology blueprint.

    Subclasses override :meth:`build`; the constructor forwards its arguments to
    it, exactly like Mininet's ``Topo``.
    """

    def __init__(self, *args, **params):
        self._hosts = []
        self._switches = []
        self._links = []
        self.node_info = {}
        self.link_info = {}
        self.ports = {}
        self.hopts = dict(params.pop("hopts", {}))
        self.sopts = dict(params.pop("sopts", {}))
        self.lopts = dict(params.pop("lopts", {}))
        self.g = WeightedGraph()
        self.build(*args, **params)

    # ------------------------------------------------------------------
    # build hook
    # ------------------------------------------------------------------
    def build(self, *args, **params):
        """Override to describe the topology."""
        return None

    # ------------------------------------------------------------------
    # node / link creation
    # ------------------------------------------------------------------
    def addNode(self, name, **opts):
        self.node_info[name] = dict(opts)
        self.g.add_node(name)
        self.ports.setdefault(name, {})
        return name

    def addHost(self, name, **opts):
        """Register a host in the blueprint and return its name."""
        merged = dict(self.hopts)
        merged.update(opts)
        merged.setdefault("isSwitch", False)
        self.addNode(name, **merged)
        if name not in self._hosts:
            self._hosts.append(name)
        return name

    def addSwitch(self, name, **opts):
        """Register a switch in the blueprint and return its name."""
        merged = dict(self.sopts)
        merged.update(opts)
        merged["isSwitch"] = True
        self.addNode(name, **merged)
        if name not in self._switches:
            self._switches.append(name)
        return name

    def addLink(self, node1, node2, port1=None, port2=None, **opts):
        """Register a link between two already-added nodes."""
        merged = dict(self.lopts)
        merged.update(opts)
        if port1 is None:
            port1 = self._newPort(node1)
        if port2 is None:
            port2 = self._newPort(node2)
        self.ports.setdefault(node1, {})[port1] = (node2, port2)
        self.ports.setdefault(node2, {})[port2] = (node1, port1)
        merged["port1"] = port1
        merged["port2"] = port2
        self._links.append((node1, node2, merged))
        self.link_info[(node1, node2)] = merged
        self.g.add_edge(node1, node2, **merged)
        return (node1, node2)

    def _newPort(self, node):
        used = self.ports.setdefault(node, {})
        return len(used)

    # ------------------------------------------------------------------
    # queries
    # ------------------------------------------------------------------
    def hosts(self, sort=True):
        """Host names in the blueprint."""
        return sorted(self._hosts, key=self._nameKey) if sort else list(self._hosts)

    def switches(self, sort=True):
        """Switch names in the blueprint."""
        return sorted(self._switches, key=self._nameKey) if sort else list(self._switches)

    def nodes(self, sort=True):
        """All node names (switches first, mirroring Mininet)."""
        return self.switches(sort) + self.hosts(sort)

    def links(self, sort=True, withKeys=False, withInfo=False):
        """Links as ``(node1, node2)`` pairs (or with their option dicts)."""
        links = list(self._links)
        if sort:
            links = sorted(links, key=lambda l: (self._nameKey(l[0]),
                                                 self._nameKey(l[1])))
        if withInfo:
            return [(a, b, dict(o)) for a, b, o in links]
        return [(a, b) for a, b, _ in links]

    def isSwitch(self, name):
        return bool(self.node_info.get(name, {}).get("isSwitch", False))

    def nodeInfo(self, name):
        return dict(self.node_info.get(name, {}))

    def linkInfo(self, node1, node2):
        info = self.link_info.get((node1, node2))
        if info is None:
            info = self.link_info.get((node2, node1), {})
        return dict(info)

    def port(self, src, dst):
        """Return ``(src_port, dst_port)`` of the link between two nodes."""
        for port, (peer, peer_port) in self.ports.get(src, {}).items():
            if peer == dst:
                return (port, peer_port)
        return (None, None)

    @staticmethod
    def _nameKey(name):
        """Sort ``h2`` before ``h10`` (natural ordering)."""
        prefix = "".join(ch for ch in name if not ch.isdigit())
        digits = "".join(ch for ch in name if ch.isdigit())
        return (prefix, int(digits) if digits else 0)

    def __repr__(self):
        return "<%s hosts=%d switches=%d links=%d>" % (
            self.__class__.__name__, len(self._hosts), len(self._switches),
            len(self._links))


class SingleSwitchTopo(Topo):
    """A single switch connected to ``k`` hosts."""

    def build(self, k=2, **opts):
        self.k = k
        switch = self.addSwitch("s1")
        for i in range(1, k + 1):
            host = self.addHost("h%d" % i)
            self.addLink(host, switch, **opts)


class LinearTopo(Topo):
    """``k`` switches in a chain, each carrying ``n`` hosts.

    ``LinearTopo(k=3)`` builds ``h1-s1-s2-s3-h3`` with h2 hanging off s2.
    """

    def build(self, k=2, n=1, **opts):
        self.k = k
        self.n = n
        last_switch = None
        for i in range(1, k + 1):
            switch = self.addSwitch("s%d" % i)
            for j in range(n):
                host_num = (i - 1) * n + j + 1
                host = self.addHost("h%d" % host_num)
                self.addLink(host, switch, **opts)
            if last_switch is not None:
                self.addLink(last_switch, switch, **opts)
            last_switch = switch


class TreeTopo(Topo):
    """Tree of switches of the given ``depth`` and ``fanout``, hosts at leaves.

    ``TreeTopo(depth=d, fanout=f)`` has ``f**d`` hosts and
    ``(f**d - 1) / (f - 1)`` switches (``d`` switches when ``fanout == 1``).
    """

    def build(self, depth=1, fanout=2, **opts):
        self.depth = depth
        self.fanout = fanout
        self._lopts_build = dict(opts)
        self.hostNum = 1
        self.switchNum = 1
        self.addTree(depth, fanout)

    def addTree(self, depth, fanout):
        """Recursively add a subtree and return the name of its root node."""
        isSwitch = depth > 0
        if isSwitch:
            node = self.addSwitch("s%d" % self.switchNum)
            self.switchNum += 1
            for _ in range(fanout):
                child = self.addTree(depth - 1, fanout)
                self.addLink(node, child, **self._lopts_build)
        else:
            node = self.addHost("h%d" % self.hostNum)
            self.hostNum += 1
        return node


class MinimalTopo(Topo):
    """Two hosts on one switch (Mininet's default topology)."""

    def build(self, **opts):
        switch = self.addSwitch("s1")
        for i in (1, 2):
            self.addLink(self.addHost("h%d" % i), switch, **opts)


class RingTopo(Topo):
    """``k`` switches in a ring, each carrying one host.

    A ring gives every switch pair a redundant path, which makes it the natural
    topology for link-failure-recovery experiments.
    """

    def build(self, k=4, n=1, **opts):
        self.k = k
        self.n = n
        switches = []
        for i in range(1, k + 1):
            switch = self.addSwitch("s%d" % i)
            switches.append(switch)
            for j in range(n):
                host_num = (i - 1) * n + j + 1
                self.addLink(self.addHost("h%d" % host_num), switch, **opts)
        for i in range(k):
            if k > 2 or i == 0:
                self.addLink(switches[i], switches[(i + 1) % k], **opts)
=========NET
"""The Mininet simulation engine.

:class:`Mininet` owns the instantiated nodes and links and answers the questions
an experiment asks of an emulated network: is a pair of hosts reachable, what
throughput does ``iperf`` report between them, and what is the round-trip time.

Reachability and paths are resolved on a :class:`netsim.graph.WeightedGraph`
built from the links, so higher layers (WiFi, containers, P4, the SDN
controller) can reuse the same routing substrate.
"""

from .graph import WeightedGraph
from .link import Link, TCLink
from .node import Controller, Host, OVSSwitch, Switch
from .packet import Packet, PacketTrace
from .utils import (compute_bottleneck_bw, compute_path_delay,
                    compute_path_loss_rate, generate_ip)


class Mininet:
    """Network emulation engine built from a :class:`netsim.topo.Topo`."""

    def __init__(self, topo=None, switch=OVSSwitch, host=Host,
                 controller=Controller, link=TCLink, ipBase="10.0.0.0/8",
                 build=True, autoSetMacs=False, autoStaticArp=False,
                 waitConnected=False, **params):
        self.topo = topo
        self.switch = switch
        self.host = host
        self.controller = controller
        self.link = link
        self.ipBase = ipBase
        self.ipBaseNum = ".".join(ipBase.split("/")[0].split(".")[:2])
        self.autoSetMacs = autoSetMacs
        self.autoStaticArp = autoStaticArp
        self.waitConnected = waitConnected
        self.params = dict(params)

        self.hosts = []
        self.switches = []
        self.controllers = []
        self.links = []
        self.nameToNode = {}
        self.graph = WeightedGraph()
        self.built = False
        self.started = False
        self.nextIP = 0

        if topo is not None and build:
            self.build()

    # ------------------------------------------------------------------
    # construction
    # ------------------------------------------------------------------
    def addHost(self, name, cls=None, **params):
        """Instantiate a host, register it and return it."""
        cls = cls or self.host
        host = cls(name, **params)
        self.hosts.append(host)
        self._register(host)
        return host

    def addSwitch(self, name, cls=None, **params):
        """Instantiate a switch, register it and return it."""
        cls = cls or self.switch
        switch = cls(name, **params)
        self.switches.append(switch)
        self._register(switch)
        return switch

    def addController(self, name="c0", cls=None, **params):
        """Instantiate a controller, register it and return it."""
        cls = cls or self.controller
        ctrl = cls(name, **params) if not isinstance(name, Controller) else name
        self.controllers.append(ctrl)
        self._register(ctrl)
        return ctrl

    def addLink(self, node1, node2, port1=None, port2=None, cls=None,
                **params):
        """Create a link between two nodes (names or objects) and return it."""
        node1 = self._resolve(node1)
        node2 = self._resolve(node2)
        cls = cls or self.link
        params.pop("isSwitch", None)
        link = cls(node1, node2, port1=port1, port2=port2, **params)
        self.links.append(link)
        self.graph.add_edge(node1.name, node2.name, **link.attrs())
        return link

    def _register(self, node):
        self.nameToNode[node.name] = node
        self.graph.add_node(node.name)
        return node

    def _resolve(self, node):
        if isinstance(node, str):
            return self.nameToNode[node]
        return node

    def build(self):
        """Instantiate the topology: controller, switches, hosts and links."""
        if self.topo is not None:
            self.buildFromTopo(self.topo)
        self.built = True
        return self

    def buildFromTopo(self, topo):
        """Create nodes and links described by ``topo``."""
        if self.controller is not None and not self.controllers:
            self.addController("c0")
        for name in topo.switches():
            opts = topo.nodeInfo(name)
            opts.pop("isSwitch", None)
            cls = opts.pop("cls", None)
            self.addSwitch(name, cls=cls, **opts)
        for name in topo.hosts():
            opts = topo.nodeInfo(name)
            opts.pop("isSwitch", None)
            cls = opts.pop("cls", None)
            self.addHost(name, cls=cls, **opts)
        for node1, node2, opts in topo.links(sort=True, withInfo=True):
            opts = dict(opts)
            cls = opts.pop("cls", None)
            self.addLink(node1, node2, cls=cls, **opts)
        for switch in self.switches:
            for ctrl in self.controllers:
                switch.attach(ctrl)
                if hasattr(ctrl, "add_switch"):
                    ctrl.add_switch(switch)
        return self

    # ------------------------------------------------------------------
    # lifecycle
    # ------------------------------------------------------------------
    def start(self):
        """Start the network: assign host IP addresses."""
        if not self.built:
            self.build()
        for index, host in enumerate(self.hosts):
            if host.ip is None:
                host.setIP(generate_ip(index, base=self.ipBaseNum))
            if self.autoSetMacs and host.mac is None:
                host.setMAC("00:00:00:00:%02x:%02x" %
                            ((index + 1) // 256, (index + 1) % 256))
        for switch in self.switches:
            switch.start(self.controllers)
        self.nextIP = len(self.hosts)
        self.started = True
        return self

    def stop(self):
        """Stop the network."""
        for node in list(self.hosts) + list(self.switches) + list(self.controllers):
            node.stop()
        self.started = False
        return self

    # ------------------------------------------------------------------
    # lookups
    # ------------------------------------------------------------------
    def getNodeByName(self, *args):
        if len(args) == 1:
            return self.nameToNode[args[0]]
        return [self.nameToNode[n] for n in args]

    get = getNodeByName

    def __getitem__(self, key):
        return self.nameToNode[key]

    def __contains__(self, key):
        return key in self.nameToNode

    def __iter__(self):
        return iter(self.nameToNode)

    def __len__(self):
        return len(self.nameToNode)

    def keys(self):
        return list(self.nameToNode)

    def values(self):
        return list(self.nameToNode.values())

    def items(self):
        return list(self.nameToNode.items())

    def total_nodes(self):
        """Number of hosts plus switches (controllers are not data-plane nodes)."""
        return len(self.hosts) + len(self.switches)

    def linksBetween(self, node1, node2):
        """All links connecting the two nodes."""
        n1 = getattr(node1, "name", node1)
        n2 = getattr(node2, "name", node2)
        return [l for l in self.links if l.connects(n1, n2)]

    def isSwitch(self, name):
        node = self.nameToNode.get(getattr(name, "name", name))
        return isinstance(node, Switch)

    # ------------------------------------------------------------------
    # path helpers
    # ------------------------------------------------------------------
    def path(self, src, dst):
        """Shortest node-name path between two nodes, or None."""
        return self.graph.shortest_path(getattr(src, "name", src),
                                        getattr(dst, "name", dst))

    def path_link_attrs(self, path):
        """Per-hop link attribute dicts along a node-name path."""
        attrs = []
        if not path:
            return attrs
        for u, v in zip(path, path[1:]):
            attrs.append(self.graph.get_edge(u, v) or {})
        return attrs

    def path_bandwidth(self, path):
        """Bottleneck bandwidth (Mbps) of a node-name path."""
        bws = [a.get("bw", Link.DEFAULT_BW) for a in self.path_link_attrs(path)]
        return compute_bottleneck_bw(bws)

    def path_delay(self, path):
        """One-way delay (ms) of a node-name path."""
        return compute_path_delay([a.get("delay", 0.0)
                                   for a in self.path_link_attrs(path)])

    def path_loss(self, path):
        """End-to-end loss probability (0-1) of a node-name path."""
        return compute_path_loss_rate([a.get("loss", 0.0) / 100.0
                                       for a in self.path_link_attrs(path)])

    def path_switches(self, path):
        """Switch nodes traversed by a node-name path."""
        out = []
        for name in path or []:
            node = self.nameToNode.get(name)
            if isinstance(node, Switch):
                out.append(node)
        return out

    def switch_overhead_factor(self, path):
        """Combined throughput factor of every switch hop on the path.

        Each switch hop costs ``Switch.FORWARDING_OVERHEAD`` (2%), applied
        multiplicatively so that N switches yield ``0.98 ** N``.
        """
        factor = 1.0
        for switch in self.path_switches(path):
            factor *= (1.0 - getattr(switch, "FORWARDING_OVERHEAD",
                                     Switch.FORWARDING_OVERHEAD))
        return factor

    # ------------------------------------------------------------------
    # measurements
    # ------------------------------------------------------------------
    def _host_list(self, hosts=None):
        if hosts is None:
            return list(self.hosts)
        return [self._resolve(h) for h in hosts]

    def ping(self, hosts=None, timeout=None):
        """Return the packet loss percentage across all ordered host pairs.

        A pair with no path through the topology counts as fully lost; otherwise
        the pair contributes the end-to-end loss probability of its path.
        """
        hosts = self._host_list(hosts)
        lost = 0.0
        packets = 0
        for src in hosts:
            for dst in hosts:
                if src is dst:
                    continue
                packets += 1
                path = self.path(src, dst)
                if not path:
                    lost += 1.0
                else:
                    lost += self.path_loss(path)
        if packets == 0:
            return 0.0
        return 100.0 * lost / packets

    def pingAll(self, timeout=None):
        """Ping between all hosts; returns the loss percentage."""
        return self.ping(self.hosts, timeout=timeout)

    def pingPair(self, hosts=None):
        """Ping between the first two hosts; returns the loss percentage."""
        hosts = self._host_list(hosts)
        return self.ping(hosts[:2])

    def pingFull(self, hosts=None):
        """Per-pair results: ``(src, dst, loss_pct, rtt_ms)`` tuples."""
        hosts = self._host_list(hosts)
        results = []
        for src in hosts:
            for dst in hosts:
                if src is dst:
                    continue
                path = self.path(src, dst)
                if not path:
                    results.append((src, dst, 100.0, None))
                else:
                    results.append((src, dst, 100.0 * self.path_loss(path),
                                    2.0 * self.path_delay(path)))
        return results

    def pingAllFull(self):
        return self.pingFull(self.hosts)

    def iperf(self, hosts=None, l4Type="TCP", udpBw="10M", fmt=None,
              seconds=5, port=5001):
        """Measured bandwidth (Mbps) between two hosts.

        The path's bottleneck bandwidth is reduced by 2% per traversed switch.
        """
        hosts = self._host_list(hosts)
        if len(hosts) < 2:
            if len(self.hosts) < 2:
                return 0.0
            hosts = [self.hosts[0], self.hosts[-1]]
        client, server = hosts[0], hosts[1]
        path = self.path(client, server)
        if not path:
            return 0.0
        bw = self.path_bandwidth(path)
        return bw * self.switch_overhead_factor(path)

    def iperfPair(self, hosts=None):
        """``(server_result, client_result)`` pair, as real Mininet returns."""
        bw = self.iperf(hosts)
        return (bw, bw)

    def rtt(self, src, dst):
        """Round-trip time (ms) between two hosts, or None if unreachable."""
        path = self.path(src, dst)
        if not path:
            return None
        return 2.0 * self.path_delay(path)

    def avg_rtt(self, hosts=None):
        """Average round-trip time (ms) over all distinct host pairs."""
        hosts = self._host_list(hosts)
        total = 0.0
        pairs = 0
        for i, src in enumerate(hosts):
            for dst in hosts[i + 1:]:
                rtt = self.rtt(src, dst)
                if rtt is None:
                    continue
                total += rtt
                pairs += 1
        if pairs == 0:
            return 0.0
        return total / pairs

    def avg_hops(self, hosts=None):
        """Average hop count over all distinct host pairs."""
        hosts = self._host_list(hosts)
        total = 0
        pairs = 0
        for i, src in enumerate(hosts):
            for dst in hosts[i + 1:]:
                path = self.path(src, dst)
                if not path:
                    continue
                total += len(path) - 1
                pairs += 1
        return (total / pairs) if pairs else 0.0

    def send_packet(self, src, dst, size_bytes=1500, protocol="ICMP"):
        """Trace a packet from ``src`` to ``dst`` and return its PacketTrace."""
        src = self._resolve(src)
        dst = self._resolve(dst)
        packet = Packet(src_ip=src.ip or "0.0.0.0", dst_ip=dst.ip or "0.0.0.0",
                        size_bytes=size_bytes, protocol=protocol)
        trace = PacketTrace(packet=packet)
        path = self.path(src, dst)
        if not path:
            return trace
        trace.add_hop(path[0], 0.0)
        for u, v in zip(path, path[1:]):
            attrs = self.graph.get_edge(u, v) or {}
            trace.add_hop(v, attrs.get("delay", 0.0))
        trace.delivered = True
        return trace

"""P4 programmable data plane.

P4 (Bosshart et al., CCR 2014) describes a packet processor as a *pipeline*: a
parser turns wire bytes into named header fields, a sequence of match-action
tables rewrites those fields and decides where the packet goes, and a deparser
serialises the result back onto the wire.  This module models that pipeline on
top of :class:`netsim.node.Switch` so a P4 switch can be dropped into any
topology the Mininet core builds.
"""

from .node import Switch
from .topo import Topo


# ----------------------------------------------------------------------
# match-action tables
# ----------------------------------------------------------------------
class P4TableEntry:
    """One rule of a :class:`P4MatchActionTable`.

    Attributes
    ----------
    match_fields : dict
        Field values the rule matches on.  ``None`` or ``"*"`` is a wildcard.
    action_name : str
        Name of the action to execute on a hit (``ipv4_forward``, ``drop``, ...).
    action_params : dict
        Parameters handed to the action (``{"port": 2}``).
    priority : int
        Higher priority wins when several rules match.
    hits : int
        Number of packets that matched this rule.
    """

    def __init__(self, match_fields, action_name, action_params=None,
                 priority=0):
        self.match_fields = dict(match_fields or {})
        self.action_name = action_name
        self.action_params = dict(action_params or {})
        self.priority = int(priority)
        self.hits = 0

    #: Aliases matching the vocabulary used elsewhere in the codebase.
    @property
    def match(self):
        return self.match_fields

    @property
    def action(self):
        return self.action_name

    @property
    def specificity(self):
        """Number of non-wildcard fields; breaks ties between equal priorities."""
        return sum(1 for v in self.match_fields.values()
                   if v is not None and v != "*")

    def matches(self, packet_headers):
        """True when every non-wildcard field of the rule equals the header."""
        for field, expected in self.match_fields.items():
            if expected is None or expected == "*":
                continue
            if packet_headers.get(field) != expected:
                return False
        return True

    def key(self):
        """Hashable identity of the rule (its match fields)."""
        return tuple(sorted(self.match_fields.items(), key=lambda kv: str(kv[0])))

    def __repr__(self):
        return "<P4TableEntry %s -> %s%s prio=%d>" % (
            self.match_fields, self.action_name, self.action_params,
            self.priority)


class P4MatchActionTable:
    """A P4 match-action table.

    Parameters
    ----------
    name : str
        Table name as it appears in the P4 program (``ipv4_lpm``).
    match_fields : list of str
        Header fields the table keys on.
    max_size : int
        Maximum number of rules the table can hold.
    """

    def __init__(self, name, match_fields, max_size=1024):
        self.name = name
        self.match_fields = list(match_fields or [])
        self.max_size = int(max_size)
        self.entries = []
        self.hit_count = 0
        self.miss_count = 0
        self.default_action = None
        self.default_action_params = {}

    # ------------------------------------------------------------------
    # rule management
    # ------------------------------------------------------------------
    def add_rule(self, match_dict, action_name, action_params=None,
                 priority=0):
        """Install a rule and return it, or ``None`` when the table is full.

        Installing a rule whose match fields already exist replaces the old rule,
        exactly as a P4Runtime ``modify`` would.
        """
        entry = P4TableEntry(match_dict, action_name, action_params, priority)
        existing = self._find(entry.key())
        if existing is not None:
            self.entries[self.entries.index(existing)] = entry
            return entry
        if len(self.entries) >= self.max_size:
            return None
        self.entries.append(entry)
        return entry

    def delete_rule(self, match_dict):
        """Remove the rule with these match fields; returns it, or None."""
        key = P4TableEntry(match_dict, None).key()
        entry = self._find(key)
        if entry is None:
            return None
        self.entries.remove(entry)
        return entry

    def set_default_action(self, action_name, action_params=None):
        """Action applied on a table miss (P4's ``default_action``)."""
        self.default_action = action_name
        self.default_action_params = dict(action_params or {})
        return self.default_action

    def clear(self):
        """Remove every rule from the table."""
        self.entries = []
        return 0

    def size(self):
        """Number of rules currently installed."""
        return len(self.entries)

    def is_full(self):
        return len(self.entries) >= self.max_size

    def utilization(self):
        """Fraction of the table's capacity in use."""
        if self.max_size <= 0:
            return 0.0
        return len(self.entries) / float(self.max_size)

    # ------------------------------------------------------------------
    # lookup
    # ------------------------------------------------------------------
    def lookup(self, packet_headers):
        """Best-matching rule for ``packet_headers``, or ``None`` on a miss.

        Highest priority wins; equal priorities are resolved in favour of the
        more specific rule (fewer wildcards), then by installation order.
        """
        headers = packet_headers or {}
        best = None
        best_rank = None
        for index, entry in enumerate(self.entries):
            if not entry.matches(headers):
                continue
            rank = (entry.priority, entry.specificity, -index)
            if best_rank is None or rank > best_rank:
                best, best_rank = entry, rank
        if best is None:
            self.miss_count += 1
            return None
        self.hit_count += 1
        best.hits += 1
        return best

    def _find(self, key):
        for entry in self.entries:
            if entry.key() == key:
                return entry
        return None

    def __len__(self):
        return len(self.entries)

    def __iter__(self):
        return iter(self.entries)

    def __repr__(self):
        return "<P4MatchActionTable %s keys=%s rules=%d/%d>" % (
            self.name, self.match_fields, len(self.entries), self.max_size)


# ----------------------------------------------------------------------
# parser / deparser
# ----------------------------------------------------------------------
class P4Parser:
    """Extracts named header fields from raw packet bytes.

    Parameters
    ----------
    header_defs : dict
        ``{field_name: (offset, length)}`` in bytes, as a P4 ``header`` layout.
    """

    def __init__(self, header_defs):
        self.header_defs = dict(header_defs or {})

    @property
    def header_size(self):
        """Bytes a packet must carry for every field to be present."""
        if not self.header_defs:
            return 0
        return max(offset + length
                   for offset, length in self.header_defs.values())

    #: Alias: the parser's minimum accepted packet length.
    min_length = header_size

    def is_valid(self, packet_data):
        """True when ``packet_data`` is long enough to hold all headers."""
        if packet_data is None:
            return False
        return len(packet_data) >= self.header_size

    def parse(self, packet_data):
        """Return ``{field: int_value}`` for every defined header field.

        Field bytes are interpreted big-endian, matching P4's bit-string
        semantics.  An invalid (too short) packet parses to an empty dict.
        """
        if not self.is_valid(packet_data):
            return {}
        data = _as_bytes(packet_data)
        headers = {}
        for field, (offset, length) in self.header_defs.items():
            headers[field] = int.from_bytes(data[offset:offset + length],
                                            "big")
        return headers

    def payload(self, packet_data):
        """Everything after the parsed headers."""
        data = _as_bytes(packet_data)
        return data[self.header_size:]

    def __repr__(self):
        return "<P4Parser fields=%d size=%dB>" % (len(self.header_defs),
                                                  self.header_size)


class P4Deparser:
    """Reassembles packet bytes from (possibly rewritten) header fields."""

    def __init__(self, header_defs):
        self.header_defs = dict(header_defs or {})

    @property
    def header_size(self):
        if not self.header_defs:
            return 0
        return max(offset + length
                   for offset, length in self.header_defs.values())

    def deparse(self, headers, payload=b""):
        """Serialise ``headers`` back into bytes and append ``payload``."""
        buf = bytearray(self.header_size)
        for field, (offset, length) in self.header_defs.items():
            if field not in (headers or {}):
                continue
            buf[offset:offset + length] = _to_field_bytes(headers[field],
                                                          length)
        return bytes(buf) + _as_bytes(payload or b"")

    def __repr__(self):
        return "<P4Deparser fields=%d size=%dB>" % (len(self.header_defs),
                                                    self.header_size)


def _as_bytes(value):
    """Coerce str/bytearray/bytes to bytes."""
    if isinstance(value, bytes):
        return value
    if isinstance(value, bytearray):
        return bytes(value)
    if isinstance(value, str):
        return value.encode("latin-1")
    return bytes(value)


def _to_field_bytes(value, length):
    """Render a header field value as ``length`` big-endian bytes."""
    if isinstance(value, (bytes, bytearray)):
        raw = bytes(value)[:length]
        return raw.rjust(length, b"\x00")
    if isinstance(value, str):
        raw = value.encode("latin-1")[:length]
        return raw.rjust(length, b"\x00")
    return int(value).to_bytes(length, "big")


# ----------------------------------------------------------------------
# counters
# ----------------------------------------------------------------------
class P4Counter:
    """A P4 counter array counting packets and bytes per index."""

    def __init__(self, name, size):
        self.name = name
        self.size = int(size)
        self.packets = [0] * self.size
        self.bytes = [0] * self.size

    def increment(self, index, packet_bytes=0):
        """Count one packet of ``packet_bytes`` bytes at ``index``."""
        if self.size <= 0:
            return None
        index = int(index) % self.size
        self.packets[index] += 1
        self.bytes[index] += int(packet_bytes)
        return (self.packets[index], self.bytes[index])

    def read(self, index):
        """Return ``(packets, bytes)`` counted at ``index``."""
        if self.size <= 0:
            return (0, 0)
        index = int(index) % self.size
        return (self.packets[index], self.bytes[index])

    def reset(self, index=None):
        """Zero one counter cell, or the whole array when ``index`` is None."""
        if index is None:
            self.packets = [0] * self.size
            self.bytes = [0] * self.size
            return None
        if self.size <= 0:
            return (0, 0)
        index = int(index) % self.size
        self.packets[index] = 0
        self.bytes[index] = 0
        return (0, 0)

    def total_packets(self):
        """Packets counted across every index."""
        return sum(self.packets)

    def total_bytes(self):
        """Bytes counted across every index."""
        return sum(self.bytes)

    def __len__(self):
        return self.size

    def __repr__(self):
        return "<P4Counter %s size=%d packets=%d bytes=%d>" % (
            self.name, self.size, self.total_packets(), self.total_bytes())


# ----------------------------------------------------------------------
# multicast
# ----------------------------------------------------------------------
class P4MulticastGroup:
    """A multicast group: one ingress copy becomes one copy per member port."""

    def __init__(self, group_id, ports=None):
        self.group_id = group_id
        self.ports = list(ports or [])

    def add_port(self, port):
        """Add a member port (idempotent); returns the member list."""
        if port not in self.ports:
            self.ports.append(port)
        return self.ports

    def remove_port(self, port):
        """Remove a member port if present; returns the member list."""
        if port in self.ports:
            self.ports.remove(port)
        return self.ports

    def replicate(self, packet_data):
        """Return one ``(port, packet_data)`` copy per member port."""
        return [(port, packet_data) for port in self.ports]

    @property
    def num_copies(self):
        """Copies a single packet produces in this group."""
        return len(self.ports)

    def __len__(self):
        return len(self.ports)

    def __repr__(self):
        return "<P4MulticastGroup %s ports=%s>" % (self.group_id, self.ports)


# ----------------------------------------------------------------------
# pipeline result
# ----------------------------------------------------------------------
class P4PipelineResult:
    """Outcome of one packet traversing a :class:`P4Switch` pipeline."""

    def __init__(self, packet=None, headers=None, egress_port=None,
                 dropped=False, valid=True, hits=0, latency_us=0.0):
        self.packet = packet
        self.headers = dict(headers or {})
        self.egress_port = egress_port
        self.dropped = dropped
        self.valid = valid
        self.hits = hits
        self.latency_us = latency_us

    @property
    def forwarded(self):
        return self.valid and not self.dropped

    def __getitem__(self, key):
        return getattr(self, key)

    def __bool__(self):
        return bool(self.forwarded)

    def __repr__(self):
        return "<P4PipelineResult port=%s hits=%d dropped=%s valid=%s>" % (
            self.egress_port, self.hits, self.dropped, self.valid)


# ----------------------------------------------------------------------
# the switch
# ----------------------------------------------------------------------
class P4Switch(Switch):
    """A switch whose forwarding behaviour is a programmable P4 pipeline.

    Parameters
    ----------
    name : str
        Switch name.
    program : str or None
        Name of the P4 program loaded onto the switch.
    """

    #: Microseconds a packet spends in one match-action table.
    LATENCY_PER_TABLE_US = 0.5

    #: Marks nodes with a programmable data plane.
    is_programmable = True

    def __init__(self, name, program=None, **params):
        Switch.__init__(self, name, **params)
        self.program = program
        self.tables = []
        self.counters = []
        self.multicast_groups = {}
        self.parser = None
        self.deparser = None
        self.packets_processed = 0
        self.packets_dropped = 0

    # ------------------------------------------------------------------
    # pipeline construction
    # ------------------------------------------------------------------
    def add_table(self, table):
        """Append a match-action table to the pipeline and return it."""
        self.tables.append(table)
        return table

    def add_counter(self, counter):
        """Register a counter array and return it."""
        self.counters.append(counter)
        return counter

    def add_multicast_group(self, group):
        """Register a :class:`P4MulticastGroup` and return it."""
        self.multicast_groups[group.group_id] = group
        return group

    def set_parser(self, parser):
        """Install the parser stage."""
        self.parser = parser
        return parser

    def set_deparser(self, deparser):
        """Install the deparser stage."""
        self.deparser = deparser
        return deparser

    def get_table(self, name):
        """Return the table called ``name``, or None."""
        for table in self.tables:
            if table.name == name:
                return table
        return None

    def get_counter(self, name):
        """Return the counter called ``name``, or None."""
        for counter in self.counters:
            if counter.name == name:
                return counter
        return None

    def get_multicast_group(self, group_id):
        return self.multicast_groups.get(group_id)

    def table_entries(self):
        """Total number of rules installed across every table on the switch."""
        return sum(table.size() for table in self.tables)

    # ------------------------------------------------------------------
    # pipeline timing
    # ------------------------------------------------------------------
    @property
    def pipeline_latency_us(self):
        """Pipeline latency in microseconds: 0.5 us per match-action table."""
        return self.LATENCY_PER_TABLE_US * len(self.tables)

    @property
    def pipeline_latency_ms(self):
        return self.pipeline_latency_us / 1000.0

    # ------------------------------------------------------------------
    # packet processing
    # ------------------------------------------------------------------
    def process_packet(self, packet_data):
        """Run the full pipeline over ``packet_data``.

        parse -> every match-action table in order -> deparse.  Each table hit
        applies its action to the header set: ``drop`` discards the packet,
        anything carrying a ``port``/``egress_port`` parameter sets the egress
        port, and remaining parameters named after a header field rewrite it.
        Registered counters are incremented once per accepted packet.
        """
        if self.parser is not None and not self.parser.is_valid(packet_data):
            return P4PipelineResult(packet=None, valid=False, dropped=True,
                                    latency_us=self.pipeline_latency_us)

        if self.parser is not None:
            headers = self.parser.parse(packet_data)
            payload = self.parser.payload(packet_data)
        else:
            headers = {}
            payload = _as_bytes(packet_data or b"")

        self.packets_processed += 1
        packet_bytes = len(packet_data) if packet_data is not None else 0
        counter_index = None
        egress_port = None
        dropped = False
        hits = 0

        for table in self.tables:
            entry = table.lookup(headers)
            if entry is None:
                if table.default_action == "drop":
                    dropped = True
                continue
            hits += 1
            port, drop, index = self._apply_action(entry, headers)
            if port is not None:
                egress_port = port
            if drop:
                dropped = True
            if index is not None:
                counter_index = index

        if counter_index is None:
            counter_index = self.packets_processed - 1
        for counter in self.counters:
            counter.increment(counter_index, packet_bytes)

        if dropped:
            self.packets_dropped += 1
            return P4PipelineResult(packet=None, headers=headers,
                                    egress_port=None, dropped=True,
                                    hits=hits,
                                    latency_us=self.pipeline_latency_us)

        if self.deparser is not None:
            out = self.deparser.deparse(headers, payload)
        else:
            out = _as_bytes(packet_data or b"")
        return P4PipelineResult(packet=out, headers=headers,
                                egress_port=egress_port, hits=hits,
                                latency_us=self.pipeline_latency_us)

    @staticmethod
    def _apply_action(entry, headers):
        """Apply one action; returns ``(egress_port, drop, counter_index)``."""
        if entry.action_name in ("drop", "_drop", "mark_to_drop"):
            return (None, True, entry.action_params.get("counter_index"))
        port = None
        index = None
        for key, value in entry.action_params.items():
            if key in ("port", "egress_port", "egress_spec"):
                port = value
            elif key == "counter_index":
                index = value
            elif key.startswith("set_"):
                headers[key[4:]] = value
            else:
                headers[key] = value
        return (port, False, index)

    def multicast(self, group_id, packet_data):
        """Replicate a packet into a registered multicast group."""
        group = self.multicast_groups.get(group_id)
        if group is None:
            return []
        return group.replicate(packet_data)

    def __repr__(self):
        return "<P4Switch %s program=%s tables=%d rules=%d>" % (
            self.name, self.program, len(self.tables), self.table_entries())


# ----------------------------------------------------------------------
# topology
# ----------------------------------------------------------------------
class P4Topology(Topo):
    """A linear chain of P4 switches, each carrying ``num_hosts_per_switch`` hosts.

    ``P4Topology(4, 1, bw=1000, delay=1.0)`` yields ``h1-s1-s2-s3-s4-h4`` with
    every switch instantiated as a :class:`P4Switch`.
    """

    def __init__(self, num_switches=2, num_hosts_per_switch=1, **link_params):
        Topo.__init__(self, num_switches, num_hosts_per_switch, **link_params)

    def build(self, num_switches=2, num_hosts_per_switch=1, program=None,
              **link_params):
        self.num_switches = int(num_switches)
        self.num_hosts_per_switch = int(num_hosts_per_switch)
        self.program = program
        self.p4_switches = []
        last = None
        for i in range(1, self.num_switches + 1):
            switch = self.addP4Switch("s%d" % i, program=program)
            for j in range(self.num_hosts_per_switch):
                host_num = (i - 1) * self.num_hosts_per_switch + j + 1
                self.addLink(self.addHost("h%d" % host_num), switch,
                             **link_params)
            if last is not None:
                self.addLink(last, switch, **link_params)
            last = switch

    def addP4Switch(self, name, **params):
        """Add a switch that the network will instantiate as a P4 switch."""
        params.setdefault("cls", P4Switch)
        params.setdefault("isP4", True)
        self.addSwitch(name, **params)
        if name not in self.p4_switches:
            self.p4_switches.append(name)
        return name

    def p4SwitchNames(self):
        """Names of the switches registered as P4-capable."""
        return list(self.p4_switches)

"""SDN controller with flow rule management.

The controller owns the control plane: it discovers the topology, computes
shortest paths with Dijkstra's algorithm and pushes OpenFlow-style flow rules
into the per-switch :class:`FlowTable`.  Two strategies are modelled -- a
:class:`ReactiveController` that installs rules when a packet misses, and a
:class:`ProactiveController` that pre-installs the full forwarding state -- plus
the timeout eviction and link-failure recovery that keep the tables honest.
"""

import heapq

from .node import Switch


# ----------------------------------------------------------------------
# flow rules
# ----------------------------------------------------------------------
class FlowRule:
    """An OpenFlow-style flow entry.

    Parameters
    ----------
    match_fields : dict
        Fields the rule matches on, e.g. ``{"dst_ip": "10.0.0.1", "in_port": 1}``.
        ``None`` or ``"*"`` is a wildcard.
    actions : list of dict
        Actions applied on a match, e.g. ``[{"type": "output", "port": 2}]``.
    priority : int
        Higher priority wins when several rules match.
    idle_timeout : float
        Seconds of inactivity before the rule is evicted (0 = permanent).
    hard_timeout : float
        Seconds after installation before the rule is evicted (0 = permanent).
    """

    def __init__(self, match_fields, actions, priority=100, idle_timeout=0,
                 hard_timeout=0, install_time=0.0):
        self.match_fields = dict(match_fields or {})
        self.actions = list(actions or [])
        self.priority = int(priority)
        self.idle_timeout = float(idle_timeout)
        self.hard_timeout = float(hard_timeout)
        self.install_time = float(install_time)
        self.packet_count = 0
        self.byte_count = 0

    # ------------------------------------------------------------------
    def matches(self, packet_headers):
        """True when every non-wildcard field of the rule equals the header."""
        headers = packet_headers or {}
        for field, expected in self.match_fields.items():
            if expected is None or expected == "*":
                continue
            if headers.get(field) != expected:
                return False
        return True

    def is_expired(self, current_time, last_matched_time=None):
        """True when either timeout has elapsed at ``current_time``.

        The idle timeout is measured from ``last_matched_time`` (the rule's
        installation time when it has never matched); the hard timeout is
        measured from installation.  A timeout of 0 means "never expire".
        """
        if self.idle_timeout > 0:
            reference = (self.install_time if last_matched_time is None
                         else float(last_matched_time))
            if current_time - reference >= self.idle_timeout:
                return True
        if self.hard_timeout > 0:
            if current_time - self.install_time >= self.hard_timeout:
                return True
        return False

    def apply(self, packet_bytes=0):
        """Account one matched packet against the rule's statistics."""
        self.packet_count += 1
        self.byte_count += int(packet_bytes)
        return (self.packet_count, self.byte_count)

    @property
    def out_ports(self):
        """Ports the rule outputs to."""
        return [a.get("port") for a in self.actions
                if a.get("type") == "output" and a.get("port") is not None]

    def key(self):
        """Hashable identity of the rule: its match fields."""
        return tuple(sorted(self.match_fields.items(),
                            key=lambda kv: str(kv[0])))

    def __repr__(self):
        return "<FlowRule %s -> %s prio=%d>" % (self.match_fields,
                                                self.actions, self.priority)


class FlowTable:
    """The flow table of a single switch."""

    def __init__(self, switch_name, capacity=4096):
        self.switch_name = switch_name
        self.capacity = int(capacity)
        self.rules = []
        self.evicted = []
        self.install_failures = 0

    # ------------------------------------------------------------------
    # rule management
    # ------------------------------------------------------------------
    def install(self, rule):
        """Install a rule; returns True, or False when the table is full.

        Installing a rule whose match fields already exist replaces the old
        rule, as an OpenFlow ``FLOW_MOD`` with the same match would.
        """
        existing = self._find(rule.key())
        if existing is not None:
            self.rules[self.rules.index(existing)] = rule
            return True
        if len(self.rules) >= self.capacity:
            self.install_failures += 1
            return False
        self.rules.append(rule)
        return True

    def remove(self, match_fields):
        """Remove the rule with these match fields; returns it, or None."""
        key = FlowRule(match_fields, []).key()
        rule = self._find(key)
        if rule is None:
            return None
        self.rules.remove(rule)
        return rule

    def clear(self):
        """Remove every rule from the table."""
        self.rules = []
        return 0

    # ------------------------------------------------------------------
    # lookup and statistics
    # ------------------------------------------------------------------
    def lookup(self, packet_headers):
        """Highest-priority rule matching ``packet_headers``, or None."""
        best = None
        best_rank = None
        for index, rule in enumerate(self.rules):
            if not rule.matches(packet_headers):
                continue
            rank = (rule.priority, len(rule.match_fields), -index)
            if best_rank is None or rank > best_rank:
                best, best_rank = rule, rank
        return best

    def evict_expired(self, current_time, last_matched_times=None):
        """Evict every expired rule; returns how many were removed.

        ``last_matched_times`` supplies the idle-timeout reference per rule.  It
        may be a mapping keyed by rule object or by the rule's match key, or a
        callable taking the rule; rules missing from it fall back to their
        installation time.
        """
        expired = [rule for rule in self.rules
                   if rule.is_expired(current_time,
                                      self._last_matched(rule,
                                                         last_matched_times))]
        for rule in expired:
            self.rules.remove(rule)
        self.evicted.extend(expired)
        return len(expired)

    @staticmethod
    def _last_matched(rule, last_matched_times):
        if last_matched_times is None:
            return None
        if callable(last_matched_times):
            return last_matched_times(rule)
        if rule in last_matched_times:
            return last_matched_times[rule]
        return last_matched_times.get(rule.key())

    def stats(self):
        """``(rule, packet_count, byte_count)`` for every installed rule."""
        return [(rule, rule.packet_count, rule.byte_count)
                for rule in self.rules]

    def size(self):
        """Number of rules currently installed."""
        return len(self.rules)

    def utilization(self):
        """Fraction of the table's capacity in use."""
        if self.capacity <= 0:
            return 0.0
        return len(self.rules) / float(self.capacity)

    def __len__(self):
        return len(self.rules)

    def __iter__(self):
        return iter(self.rules)

    def _find(self, key):
        for rule in self.rules:
            if rule.key() == key:
                return rule
        return None

    def __repr__(self):
        return "<FlowTable %s rules=%d/%d>" % (self.switch_name,
                                               len(self.rules), self.capacity)


# ----------------------------------------------------------------------
# the controller
# ----------------------------------------------------------------------
class SDNController:
    """Base SDN controller: topology graph, path computation, flow tables."""

    #: Default flow table capacity handed to newly registered switches.
    TABLE_CAPACITY = 4096

    def __init__(self, name="c0", table_capacity=None):
        self.name = name
        self.table_capacity = int(table_capacity if table_capacity is not None
                                  else self.TABLE_CAPACITY)
        #: ``{node: {neighbour: weight}}`` view of the data plane.
        self.graph = {}
        #: ``{switch_name: FlowTable}``.
        self.flow_tables = {}
        self.switches = []
        #: ``{host_name: ip}`` learnt during topology discovery.
        self.hosts = {}
        #: ``{(node, neighbour): egress_port}`` learnt during discovery.
        self.ports = {}
        #: ``{(src_ip, dst_ip): path}`` for every path currently programmed.
        self.installed_paths = {}
        self.failed_links = []

    # ------------------------------------------------------------------
    # topology
    # ------------------------------------------------------------------
    def add_switch(self, switch_name):
        """Register a switch and create its flow table."""
        name = getattr(switch_name, "name", switch_name)
        if name not in self.flow_tables:
            self.flow_tables[name] = FlowTable(name,
                                               capacity=self.table_capacity)
        if name not in self.switches:
            self.switches.append(name)
        self.graph.setdefault(name, {})
        return self.flow_tables[name]

    def add_host(self, host_name, ip=None):
        """Register a host (and its IP) as a graph node."""
        name = getattr(host_name, "name", host_name)
        self.hosts[name] = ip if ip is not None else getattr(host_name, "ip",
                                                             None)
        self.graph.setdefault(name, {})
        return name

    def add_link(self, node1, node2, weight=1):
        """Add a bidirectional link to the topology graph."""
        n1 = getattr(node1, "name", node1)
        n2 = getattr(node2, "name", node2)
        self.graph.setdefault(n1, {})[n2] = weight
        self.graph.setdefault(n2, {})[n1] = weight
        return (n1, n2)

    def remove_link(self, node1, node2):
        """Remove a link from the topology graph (a link failure)."""
        n1 = getattr(node1, "name", node1)
        n2 = getattr(node2, "name", node2)
        removed = self.graph.get(n1, {}).pop(n2, None) is not None
        removed |= self.graph.get(n2, {}).pop(n1, None) is not None
        if removed:
            self.failed_links.append((n1, n2))
        return removed

    def topology_discovery(self, net):
        """Build the controller's view of ``net`` (a Mininet instance).

        Registers every switch (with a flow table), every host (with its IP) and
        every link, and records the egress port each node uses towards its
        neighbour so installed rules carry real output ports.
        """
        for switch in net.switches:
            self.add_switch(switch.name)
        for host in net.hosts:
            self.add_host(host.name, host.ip)
        for link in net.links:
            node1, node2 = link.node1, link.node2
            self.add_link(node1.name, node2.name)
            self.ports[(node1.name, node2.name)] = link.port1
            self.ports[(node2.name, node1.name)] = link.port2
        return self.graph

    def is_switch(self, name):
        """True when ``name`` is a registered switch."""
        return name in self.flow_tables

    # ------------------------------------------------------------------
    # path computation
    # ------------------------------------------------------------------
    def compute_path(self, src, dst):
        """Dijkstra shortest path from ``src`` to ``dst``.

        Returns the list of node names including both endpoints, or an empty
        list when the two nodes are not connected.  Equal-cost paths are broken
        deterministically in favour of the lexicographically smaller node.
        """
        src = getattr(src, "name", src)
        dst = getattr(dst, "name", dst)
        if src not in self.graph or dst not in self.graph:
            return []
        if src == dst:
            return [src]

        dist = {src: 0}
        prev = {src: None}
        visited = set()
        pq = [(0, src)]
        while pq:
            d, node = heapq.heappop(pq)
            if node in visited:
                continue
            visited.add(node)
            if node == dst:
                break
            for neighbour, weight in sorted(self.graph.get(node, {}).items()):
                if neighbour in visited:
                    continue
                nd = d + weight
                if neighbour not in dist or nd < dist[neighbour]:
                    dist[neighbour] = nd
                    prev[neighbour] = node
                    heapq.heappush(pq, (nd, neighbour))

        if dst not in prev:
            return []
        path = []
        node = dst
        while node is not None:
            path.append(node)
            node = prev[node]
        path.reverse()
        return path

    def compute_all_paths(self):
        """``{(src, dst): path}`` for every ordered pair of known hosts."""
        paths = {}
        names = sorted(self.hosts, key=_name_key)
        for src in names:
            for dst in names:
                if src == dst:
                    continue
                path = self.compute_path(src, dst)
                if path:
                    paths[(src, dst)] = path
        return paths

    def path_switches(self, path):
        """Registered switches traversed by ``path``, in order."""
        return [n for n in (path or []) if n in self.flow_tables]

    # ------------------------------------------------------------------
    # rule installation
    # ------------------------------------------------------------------
    def install_path_rules(self, path, src_ip, dst_ip, priority=100,
                           idle_timeout=0, hard_timeout=0):
        """Install one forwarding rule per switch along ``path``.

        Each rule matches the ``(src_ip, dst_ip)`` flow and outputs to the port
        facing the next hop.  Returns the number of rules actually installed.
        """
        installed = 0
        switches = self.path_switches(path)
        if not switches:
            return 0
        for index, name in enumerate(path):
            if name not in self.flow_tables:
                continue
            next_hop = path[index + 1] if index + 1 < len(path) else None
            port = self.ports.get((name, next_hop)) if next_hop else None
            rule = FlowRule({"src_ip": src_ip, "dst_ip": dst_ip},
                            [{"type": "output", "port": port,
                              "next_hop": next_hop}],
                            priority=priority, idle_timeout=idle_timeout,
                            hard_timeout=hard_timeout)
            if self.flow_tables[name].install(rule):
                installed += 1
        self.installed_paths[(src_ip, dst_ip)] = list(path)
        return installed

    def remove_path_rules(self, path, src_ip, dst_ip):
        """Remove the rules a previous :meth:`install_path_rules` created."""
        removed = 0
        for name in self.path_switches(path):
            if self.flow_tables[name].remove({"src_ip": src_ip,
                                              "dst_ip": dst_ip}) is not None:
                removed += 1
        self.installed_paths.pop((src_ip, dst_ip), None)
        return removed

    def total_rules_installed(self):
        """Number of rules across every switch's flow table."""
        return sum(table.size() for table in self.flow_tables.values())

    def table_utilization(self):
        """``{switch: utilization}`` for every registered switch."""
        return {name: table.utilization()
                for name, table in self.flow_tables.items()}

    def clear_all_rules(self):
        """Wipe every flow table and forget the programmed paths."""
        for table in self.flow_tables.values():
            table.clear()
        self.installed_paths = {}
        return 0

    def host_ip(self, name):
        return self.hosts.get(name)

    def host_by_ip(self, ip):
        """Name of the host owning ``ip``, or None."""
        for name, host_ip in self.hosts.items():
            if host_ip == ip:
                return name
        return None

    # ------------------------------------------------------------------
    # failure handling
    # ------------------------------------------------------------------
    @staticmethod
    def path_uses_link(path, node1, node2):
        """True when ``path`` traverses the link between the two nodes."""
        for u, v in zip(path or [], (path or [])[1:]):
            if {u, v} == {node1, node2}:
                return True
        return False

    def affected_paths(self, node1, node2):
        """Programmed flows whose path crosses the ``node1``-``node2`` link."""
        return [(flow, path) for flow, path in self.installed_paths.items()
                if self.path_uses_link(path, node1, node2)]

    def handle_link_failure(self, node1, node2):
        """Fail a link and reroute every flow that was using it.

        The rules of each affected flow are withdrawn, a fresh path is computed
        on the reduced topology and the rules are reinstalled along it.  Returns
        the number of rules reinstalled (flows left without any path contribute
        nothing).
        """
        n1 = getattr(node1, "name", node1)
        n2 = getattr(node2, "name", node2)
        affected = self.affected_paths(n1, n2)
        self.remove_link(n1, n2)
        reinstalled = 0
        for (src_ip, dst_ip), path in affected:
            self.remove_path_rules(path, src_ip, dst_ip)
            src = self.host_by_ip(src_ip) or (path[0] if path else None)
            dst = self.host_by_ip(dst_ip) or (path[-1] if path else None)
            new_path = self.compute_path(src, dst) if src and dst else []
            if not new_path:
                continue
            reinstalled += self.install_path_rules(new_path, src_ip, dst_ip)
        return reinstalled

    def __repr__(self):
        return "<%s %s switches=%d rules=%d>" % (
            self.__class__.__name__, self.name, len(self.flow_tables),
            self.total_rules_installed())


class ReactiveController(SDNController):
    """Installs flow rules on demand, driven by table-miss packet-in events."""

    #: Milliseconds the controller spends handling one packet-in event.
    PACKET_IN_TIME_MS = 0.05

    def __init__(self, name="c0", packet_in_time_ms=None, **params):
        SDNController.__init__(self, name, **params)
        self.packet_in_count = 0
        self.packet_in_time_ms = float(
            packet_in_time_ms if packet_in_time_ms is not None
            else self.PACKET_IN_TIME_MS)
        self.rules_installed = 0

    def handle_packet_in(self, switch_name, packet_headers):
        """Handle a table miss: compute the path and install rules along it.

        Returns the number of rules installed for this event (0 when the flow
        was already programmed or no path exists).
        """
        self.packet_in_count += 1
        name = getattr(switch_name, "name", switch_name)
        table = self.flow_tables.get(name)
        if table is not None and table.lookup(packet_headers) is not None:
            return 0
        src_ip = (packet_headers or {}).get("src_ip")
        dst_ip = (packet_headers or {}).get("dst_ip")
        src = self.host_by_ip(src_ip)
        dst = self.host_by_ip(dst_ip)
        if src is None or dst is None:
            return 0
        path = self.compute_path(src, dst)
        if not path:
            return 0
        installed = self.install_path_rules(path, src_ip, dst_ip)
        self.rules_installed += installed
        return installed

    def total_processing_time_ms(self):
        """Milliseconds spent on every packet-in event handled so far."""
        return self.packet_in_count * self.packet_in_time_ms

    def throughput(self):
        """Packet-in events handled per simulated second."""
        total_ms = self.total_processing_time_ms()
        if total_ms <= 0:
            return 0.0
        return self.packet_in_count / (total_ms / 1000.0)


class ProactiveController(SDNController):
    """Pre-installs the complete forwarding state before any traffic flows."""

    #: Milliseconds one flow-rule installation costs.
    RULE_INSTALL_TIME_MS = 0.1

    def __init__(self, name="c0", rule_install_time_ms=None, **params):
        SDNController.__init__(self, name, **params)
        self.rule_install_time_ms = float(
            rule_install_time_ms if rule_install_time_ms is not None
            else self.RULE_INSTALL_TIME_MS)
        self.rules_installed = 0

    def install_all_rules(self, hosts_with_ips=None, priority=100):
        """Install forwarding rules for every ordered source/destination pair.

        ``hosts_with_ips`` may be a ``{name: ip}`` mapping, a list of
        ``(name, ip)`` pairs or a list of host objects; it defaults to the hosts
        learnt during topology discovery.  Returns the number of rules installed.
        """
        hosts = self._normalise_hosts(hosts_with_ips)
        installed = 0
        names = sorted(hosts, key=_name_key)
        for src in names:
            for dst in names:
                if src == dst:
                    continue
                path = self.compute_path(src, dst)
                if not path:
                    continue
                installed += self.install_path_rules(path, hosts[src],
                                                    hosts[dst],
                                                    priority=priority)
        self.rules_installed += installed
        return installed

    def _normalise_hosts(self, hosts_with_ips):
        if hosts_with_ips is None:
            return dict(self.hosts)
        if isinstance(hosts_with_ips, dict):
            hosts = dict(hosts_with_ips)
        else:
            hosts = {}
            for item in hosts_with_ips:
                if isinstance(item, (tuple, list)):
                    hosts[item[0]] = item[1]
                else:
                    hosts[getattr(item, "name", item)] = getattr(item, "ip",
                                                                 None)
        for name, ip in hosts.items():
            self.add_host(name, ip)
        return hosts

    def total_install_time(self):
        """Milliseconds needed to install every rule currently programmed."""
        return self.total_rules_installed() * self.rule_install_time_ms


def _name_key(name):
    """Natural sort key so ``h2`` orders before ``h10``."""
    prefix = "".join(ch for ch in name if not ch.isdigit())
    digits = "".join(ch for ch in name if ch.isdigit())
    return (prefix, int(digits) if digits else 0)


def attach_controller(net, controller):
    """Run topology discovery for ``controller`` against ``net``.

    Also attaches the controller to every :class:`~netsim.node.Switch` so the
    data plane knows who programs it.
    """
    controller.topology_discovery(net)
    for switch in net.switches:
        if isinstance(switch, Switch):
            switch.attach(controller)
    return controller

